/* ============================================================
   SMALL HELPERS
   ============================================================ */
function scoreColor(v) {
  if (v >= 80) return C.success;
  if (v >= 60) return C.warning;
  return C.danger;
}
function priorityColor(p) {
  if (p === "High") return C.danger;
  if (p === "Medium") return C.warning;
  return C.success;
}
function ScoreBar({ label, value }) {
  return (
    <div style={{ marginBottom: 10 }}>
      <div style={{ display: "flex", justifyContent: "space-between", fontSize: 13, marginBottom: 4 }}>
        <span style={{ color: C.textSub }}>{label}</span>
        <span style={{ color: C.text, fontWeight: 600 }}>{value}</span>
      </div>
      <div style={{ height: 6, borderRadius: 3, background: C.border, overflow: "hidden" }}>
        <div style={{ width: `${value}%`, height: "100%", background: scoreColor(value), borderRadius: 3 }} />
      </div>
    </div>
  );
}
function Pill({ children, tone = "default" }) {
  const map = {
    default: { bg: "rgba(155,31,174,0.12)", color: C.accent2, border: "rgba(155,31,174,0.35)" },
    success: { bg: "rgba(54,201,143,0.12)", color: C.success, border: "rgba(54,201,143,0.35)" },
    warning: { bg: "rgba(245,185,66,0.12)", color: C.warning, border: "rgba(245,185,66,0.35)" },
    danger: { bg: "rgba(239,98,98,0.12)", color: C.danger, border: "rgba(239,98,98,0.35)" },
    muted: { bg: "rgba(124,113,137,0.10)", color: C.textSub, border: C.border },
  };
  const s = map[tone];
  return (
    <span style={{
      display: "inline-flex", alignItems: "center", gap: 4, fontSize: 12, fontWeight: 600,
      padding: "3px 10px", borderRadius: 20, background: s.bg, color: s.color, border: `1px solid ${s.border}`,
    }}>{children}</span>
  );
}
function SectionLabel({ children }) {
  return <div style={{ color: C.accent, fontSize: 13, fontWeight: 600, letterSpacing: 0.2, marginBottom: 10 }}>{children}</div>;
}
function Button({ children, onClick, variant = "primary", icon: Icon, style = {}, type = "button" }) {
  const base = {
    display: "inline-flex", alignItems: "center", gap: 8, padding: "13px 26px", borderRadius: 999,
    fontSize: 14.5, fontWeight: 700, letterSpacing: 0.3, cursor: "pointer", border: "1px solid transparent", transition: "all .15s ease",
  };
  const variants = {
    primary: { background: `linear-gradient(120deg, ${C.accent}, ${C.accent2})`, color: "#FFFFFF", boxShadow: "0 8px 20px rgba(155,31,174,0.28)" },
    secondary: { background: "transparent", color: C.text, border: `1.5px solid ${C.border}` },
    ghost: { background: C.cardEl, color: C.text },
    danger: { background: C.danger, color: "#FFFFFF" },
  };
  return (
    <button type={type} onClick={onClick} style={{ ...base, ...variants[variant], ...style }}>
      {children}{Icon && <Icon size={16} />}
    </button>
  );
}
function Card({ children, style = {}, hover = true }) {
  const [h, setH] = useState(false);
  return (
    <div
      onMouseEnter={() => hover && setH(true)}
      onMouseLeave={() => hover && setH(false)}
      style={{
        background: C.card, border: `1px solid ${C.border}`, borderRadius: 18, padding: 20,
        transform: h ? "translateY(-4px)" : "translateY(0)",
        boxShadow: h ? "0 16px 32px rgba(120,40,140,0.16)" : "0 4px 16px rgba(120,40,140,0.06)",
        transition: "all .18s ease", ...style,
      }}
    >{children}</div>
  );
}
function DataLabel({ children }) {
  return (
    <div style={{
      display: "inline-flex", alignItems: "center", gap: 6, fontSize: 11.5, color: C.textSub,
      background: "rgba(124,113,137,0.08)", border: `1px solid ${C.border}`, borderRadius: 8, padding: "4px 9px",
    }}>
      <Info size={12} />{children}
    </div>
  );
}

/* ============================================================
   AUTH (client-side, session-only demo accounts)
   ============================================================ */
function AuthModal({ open, mode, setMode, onClose, onLogin, onSignup, error }) {
  const [username, setUsername] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPw, setShowPw] = useState(false);

  useEffect(() => {
    if (open) { setUsername(""); setEmail(""); setPassword(""); setShowPw(false); }
  }, [open, mode]);

  if (!open) return null;

  function submit(e) {
    e.preventDefault();
    if (mode === "login") onLogin(username.trim(), password);
    else onSignup(username.trim(), email.trim(), password);
  }

  return (
    <div onClick={onClose} style={{
      position: "fixed", inset: 0, background: "rgba(4,5,7,0.72)", backdropFilter: "blur(3px)",
      display: "flex", alignItems: "center", justifyContent: "center", zIndex: 100, padding: 20,
    }}>
      <div onClick={(e) => e.stopPropagation()} style={{
        width: "100%", maxWidth: 400, background: C.card, border: `1px solid ${C.border}`,
        borderRadius: 16, padding: 28, position: "relative",
      }}>
        <button onClick={onClose} style={{ position: "absolute", top: 18, right: 18, background: "none", border: "none", color: C.textSub, cursor: "pointer" }}>
          <X size={18} />
        </button>

        <div style={{ display: "flex", alignItems: "center", marginBottom: 6 }}>
          <img src={LOGO_SRC} alt="IndiaQuest" style={{ height: 40, width: "auto", display: "block" }} />
        </div>
        <h2 style={{ fontFamily: "Sora, sans-serif", fontSize: 21, fontWeight: 700, margin: "14px 0 4px" }}>
          {mode === "login" ? "Welcome back" : "Create your account"}
        </h2>
        <p style={{ color: C.textSub, fontSize: 13, marginBottom: 20 }}>
          {mode === "login" ? "Sign in to submit reports and manage your safety settings." : "Sign up to report issues, save trips and share your location with contacts."}
        </p>

        <form onSubmit={submit} autoComplete="off">
          <input type="text" name="fake-username" style={{ display: "none" }} autoComplete="username" />
          <input type="password" name="fake-password" style={{ display: "none" }} autoComplete="new-password" />
          <Field label="Username">
            <div style={{ position: "relative" }}>
              <UserCircle2 size={15} style={{ position: "absolute", left: 12, top: 13, color: C.textSub }} />
              <input name="iq-username-field" autoComplete="off" data-lpignore="true" data-1p-ignore value={username} onChange={(e) => setUsername(e.target.value)} required placeholder="e.g. wanderer_23" style={{ ...inputStyle, paddingLeft: 34 }} />
            </div>
          </Field>
          {mode === "signup" && (
            <Field label="Email">
              <div style={{ position: "relative" }}>
                <Mail size={15} style={{ position: "absolute", left: 12, top: 13, color: C.textSub }} />
                <input type="email" name="iq-email-field" autoComplete="off" data-lpignore="true" data-1p-ignore value={email} onChange={(e) => setEmail(e.target.value)} required placeholder="you@example.com" style={{ ...inputStyle, paddingLeft: 34 }} />
              </div>
            </Field>
          )}
          <Field label="Password">
            <div style={{ position: "relative" }}>
              <Lock size={15} style={{ position: "absolute", left: 12, top: 13, color: C.textSub }} />
              <input type={showPw ? "text" : "password"} name="iq-password-field" autoComplete="new-password" data-lpignore="true" data-1p-ignore value={password} onChange={(e) => setPassword(e.target.value)} required minLength={4} placeholder="••••••••" style={{ ...inputStyle, paddingLeft: 34, paddingRight: 36 }} />
              <button type="button" onClick={() => setShowPw(!showPw)} style={{ position: "absolute", right: 10, top: 10, background: "none", border: "none", color: C.textSub, cursor: "pointer" }}>
                {showPw ? <EyeOff size={15} /> : <Eye size={15} />}
              </button>
            </div>
          </Field>

          {error && <div style={{ color: C.danger, fontSize: 12.5, marginBottom: 14, marginTop: -6 }}>{error}</div>}

          <Button type="submit" variant="primary" icon={mode === "login" ? LogIn : UserPlus} style={{ width: "100%", justifyContent: "center", marginTop: 4 }}>
            {mode === "login" ? "Sign in" : "Create account"}
          </Button>
        </form>

        <div style={{ textAlign: "center", marginTop: 16, fontSize: 13, color: C.textSub }}>
          {mode === "login" ? (
            <span>New to IndiaQuest? <a onClick={() => setMode("signup")} style={{ color: C.accent2, cursor: "pointer", fontWeight: 600 }}>Create an account</a></span>
          ) : (
            <span>Already have an account? <a onClick={() => setMode("login")} style={{ color: C.accent2, cursor: "pointer", fontWeight: 600 }}>Sign in</a></span>
          )}
        </div>
      </div>
    </div>
  );
}

/* ============================================================
   NAVBAR
   ============================================================ */
function Navbar({ view, setView, t, lang, setLang, mode, setMode, query, setQuery, onSearch, currentUser, onOpenAuth, onLogout }) {
  const [scrolled, setScrolled] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  const [langOpen, setLangOpen] = useState(false);
  const [userOpen, setUserOpen] = useState(false);
  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 12);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const navItems = [
    { key: "discover", label: t.nav_discover },
    { key: "plan", label: t.nav_plan },
    { key: "trusted", label: t.nav_trusted },
    { key: "safety", label: t.nav_safety },
    { key: "report", label: t.nav_report },
  ];

  return (
    <>
    <div style={{ height: 68 }} />
    <div style={{
      position: "fixed", top: 0, left: 0, right: 0, zIndex: 50,
      background: "rgba(255,255,255,0.98)",
      backdropFilter: "blur(10px)", borderBottom: `1px solid ${C.border}`,
      boxShadow: scrolled ? "0 4px 16px rgba(0,0,0,0.08)" : "0 1px 3px rgba(0,0,0,0.04)",
      transition: "box-shadow .2s ease",
    }}>
      <div style={{ maxWidth: 1320, margin: "0 auto", padding: "12px 24px", display: "flex", alignItems: "center", gap: 24 }}>
        <div onClick={() => setView("home")} style={{ display: "flex", alignItems: "center", gap: 12, cursor: "pointer" }}>
          <img src={LOGO_SRC} alt="IndiaQuest" style={{ height: 44, width: "auto", display: "block" }} />
        </div>

        <div style={{ display: "flex", gap: 4, flex: 1 }} className="b360-desktop-nav">
          {navItems.map((n) => (
            <button key={n.key} onClick={() => setView(n.key)} style={{
              background: "none", border: "none", cursor: "pointer", padding: "8px 12px", borderRadius: 8,
              color: view === n.key ? C.text : C.textSub, fontSize: 14.5, fontWeight: 500,
              borderBottom: view === n.key ? `2px solid ${C.accent}` : "2px solid transparent",
            }}>{n.label}</button>
          ))}
          <button onClick={() => setView("intelligence")} style={{
            background: "none", border: "none", cursor: "pointer", padding: "8px 12px", borderRadius: 8,
            color: view === "intelligence" || view === "business" ? C.text : C.textSub, fontSize: 14.5, fontWeight: 500,
            display: "flex", alignItems: "center", gap: 6,
            borderBottom: (view === "intelligence" || view === "business") ? `2px solid ${C.accent}` : "2px solid transparent",
          }}><LayoutDashboard size={14} />{t.nav_intel}</button>
        </div>

        <div style={{ display: "flex", alignItems: "center", gap: 10 }} className="b360-desktop-actions">
          <form onSubmit={(e) => { e.preventDefault(); onSearch(query); }} style={{ position: "relative" }}>
            <Search size={15} style={{ position: "absolute", left: 11, top: 10, color: C.textSub }} />
            <input
              value={query} onChange={(e) => setQuery(e.target.value)}
              placeholder={t.search_ph}
              style={{
                width: 210, background: C.cardEl, border: `1px solid ${C.border}`, borderRadius: 9,
                padding: "8px 12px 8px 32px", color: C.text, fontSize: 13.5, outline: "none",
              }}
            />
          </form>

          <div style={{ position: "relative" }}>
            <button onClick={() => setLangOpen(!langOpen)} style={{
              display: "flex", alignItems: "center", gap: 5, background: C.cardEl, border: `1px solid ${C.border}`,
              borderRadius: 9, padding: "8px 10px", color: C.textSub, cursor: "pointer", fontSize: 13,
            }}><Globe size={14} />{lang.toUpperCase()}<ChevronDown size={12} /></button>
            {langOpen && (
              <div style={{ position: "absolute", right: 0, top: 40, background: C.cardEl, border: `1px solid ${C.border}`, borderRadius: 10, overflow: "hidden", minWidth: 120, zIndex: 60 }}>
                {["en", "hi"].map((l) => (
                  <div key={l} onClick={() => { setLang(l); setLangOpen(false); }} style={{ padding: "9px 14px", fontSize: 13.5, cursor: "pointer", color: lang === l ? C.accent2 : C.text }}>
                    {l === "en" ? "English" : "हिन्दी (Hindi)"}
                  </div>
                ))}
              </div>
            )}
          </div>

          <div style={{ display: "flex", background: C.cardEl, border: `1px solid ${C.border}`, borderRadius: 9, padding: 3 }}>
            {["Tourist", "Authority", "Business"].map((m) => (
              <button key={m} onClick={() => { setMode(m); setView(m === "Authority" ? "intelligence" : m === "Business" ? "business" : "home"); }} style={{
                border: "none", cursor: "pointer", fontSize: 12.5, fontWeight: 600, padding: "6px 10px", borderRadius: 7,
                background: mode === m ? C.accent : "transparent", color: mode === m ? "#FFFFFF" : C.textSub,
              }}>{m}</button>
            ))}
          </div>

          <Button variant="primary" onClick={() => setView("discover")} style={{ padding: "9px 16px", fontSize: 13.5 }}>{t.explore_cta}</Button>

          <div style={{ position: "relative" }}>
            {currentUser ? (
              <>
                <button onClick={() => setUserOpen(!userOpen)} style={{
                  display: "flex", alignItems: "center", gap: 7, background: C.cardEl, border: `1px solid ${C.border}`,
                  borderRadius: 9, padding: "6px 12px 6px 8px", color: C.text, cursor: "pointer",
                }}>
                  <div style={{ width: 22, height: 22, borderRadius: "50%", background: `linear-gradient(135deg, ${C.accent}, ${C.accent2})`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 11, fontWeight: 800, color: "#FFFFFF" }}>
                    {currentUser.username[0].toUpperCase()}
                  </div>
                  <span style={{ fontSize: 13, fontWeight: 600 }}>{currentUser.username}</span>
                  <ChevronDown size={12} color={C.textSub} />
                </button>
                {userOpen && (
                  <div style={{ position: "absolute", right: 0, top: 42, background: C.cardEl, border: `1px solid ${C.border}`, borderRadius: 10, overflow: "hidden", minWidth: 160, zIndex: 60 }}>
                    <div style={{ padding: "10px 14px", fontSize: 11.5, color: C.textSub, borderBottom: `1px solid ${C.border}` }}>Signed in</div>
                    <div onClick={() => { onLogout(); setUserOpen(false); }} style={{ padding: "10px 14px", fontSize: 13.5, cursor: "pointer", color: C.danger, display: "flex", alignItems: "center", gap: 8 }}>
                      <LogOut size={13} /> Log out
                    </div>
                  </div>
                )}
              </>
            ) : (
              <Button variant="ghost" icon={LogIn} onClick={() => onOpenAuth("login")} style={{ padding: "9px 14px", fontSize: 13.5 }}>Sign In</Button>
            )}
          </div>
        </div>

        <div className="b360-mobile-actions" style={{ display: "none", alignItems: "center", gap: 6, marginLeft: "auto" }}>
          <button onClick={() => setView("discover")} style={{ background: C.cardEl, border: `1px solid ${C.border}`, borderRadius: 9, width: 36, height: 36, display: "flex", alignItems: "center", justifyContent: "center", color: C.textSub, cursor: "pointer" }}>
            <Search size={16} />
          </button>
          {currentUser ? (
            <div style={{ width: 32, height: 32, borderRadius: "50%", background: `linear-gradient(135deg, ${C.accent}, ${C.accent2})`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 13, fontWeight: 800, color: "#FFFFFF" }}>
              {currentUser.username[0].toUpperCase()}
            </div>
          ) : (
            <button onClick={() => onOpenAuth("login")} style={{ background: C.accent, border: "none", borderRadius: 9, padding: "8px 12px", color: "#FFFFFF", fontSize: 12.5, fontWeight: 600, cursor: "pointer" }}>
              Sign In
            </button>
          )}
          <button className="b360-mobile-toggle" onClick={() => setMobileOpen(!mobileOpen)} style={{ background: "none", border: "none", color: C.text }}>
            {mobileOpen ? <X size={22} /> : <Menu size={22} />}
          </button>
        </div>
      </div>

      {mobileOpen && (
        <div className="b360-mobile-panel" style={{ borderTop: `1px solid ${C.border}`, background: C.bg2, padding: 16 }}>
          {[...navItems, { key: "intelligence", label: t.nav_intel }, { key: "business", label: "Business" }].map((n) => (
            <div key={n.key} onClick={() => { setView(n.key); setMobileOpen(false); }} style={{ padding: "12px 4px", color: view === n.key ? C.accent2 : C.text, fontSize: 15, borderBottom: `1px solid ${C.border}` }}>{n.label}</div>
          ))}
          <div style={{ padding: "14px 4px 4px" }}>
            {currentUser ? (
              <Button variant="secondary" icon={LogOut} onClick={() => { onLogout(); setMobileOpen(false); }} style={{ width: "100%", justifyContent: "center" }}>Log out ({currentUser.username})</Button>
            ) : (
              <Button variant="primary" icon={LogIn} onClick={() => { onOpenAuth("login"); setMobileOpen(false); }} style={{ width: "100%", justifyContent: "center" }}>Sign In</Button>
            )}
          </div>
        </div>
      )}
      <style>{`
        @media (max-width: 900px) {
          .b360-desktop-nav, .b360-desktop-actions { display: none !important; }
          .b360-mobile-actions { display: flex !important; }
        }
        @media (min-width: 901px) {
          .b360-mobile-actions { display: none !important; }
          .b360-mobile-panel { display: none !important; }
        }
      `}</style>
    </div>
    </>
  );
}

/* ============================================================
   HOME PAGE
   ============================================================ */
function IndiaGrid() {
  const dots = useMemo(() => {
    const arr = [];
    for (let i = 0; i < 240; i++) {
      arr.push({ x: Math.random() * 100, y: Math.random() * 100, r: Math.random() > 0.94 ? 2.6 : 1.2, hi: Math.random() > 0.94 });
    }
    return arr;
  }, []);
  return (
    <svg viewBox="0 0 100 60" style={{ width: "100%", height: 220 }} preserveAspectRatio="xMidYMid meet">
      {dots.filter(d => d.y < 60).map((d, i) => (
        <circle key={i} cx={d.x} cy={d.y} r={d.r} fill={d.hi ? C.accent : C.border} opacity={d.hi ? 0.9 : 0.6} />
      ))}
    </svg>
  );
}

