function JourneyProblem() {
  const stages = [
    { k: "Discover", v: "Too much information. Not enough trusted context." },
    { k: "Plan", v: "Transport, costs and local services are often scattered." },
    { k: "Arrive", v: "Last-mile connectivity can be unclear." },
    { k: "Move", v: "Local transport and indicative prices may be difficult to understand." },
    { k: "Stay", v: "Verified accommodation options can be hard to distinguish from the rest." },
    { k: "Experience", v: "Safety, cleanliness and accessibility information may be inconsistent." },
    { k: "Return", v: "Tourist feedback often remains disconnected from improvement." },
  ];
  return (
    <div style={{ maxWidth: 1320, margin: "0 auto", padding: "90px 24px" }}>
      <SectionLabel>The problem</SectionLabel>
      <h2 style={{ fontFamily: "Sora, sans-serif", fontSize: "clamp(28px, 3.4vw, 40px)", fontWeight: 700, maxWidth: 700, marginBottom: 44 }}>
        Great destinations can still create difficult journeys.
      </h2>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))", gap: 1, background: C.border, borderRadius: 14, overflow: "hidden" }}>
        {stages.map((s) => (
          <div key={s.k} style={{ background: C.card, padding: "26px 20px", minHeight: 170 }}>
            <div style={{ color: C.accent2, fontFamily: "Sora, sans-serif", fontWeight: 700, fontSize: 15, marginBottom: 10 }}>{s.k}</div>
            <div style={{ color: C.textSub, fontSize: 13.5, lineHeight: 1.55 }}>{s.v}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

