/* ============================================================
   DISCOVER PAGE
   ============================================================ */
function DiscoverPage({ openDestination, initialQuery }) {
  const [q, setQ] = useState(initialQuery || "");
  const [stateFilter, setStateFilter] = useState("All");
  const [catFilter, setCatFilter] = useState("All");
  const [seasonFilter, setSeasonFilter] = useState("All");
  const [sortBy, setSortBy] = useState("Experience Score");
  const [accessibleOnly, setAccessibleOnly] = useState(false);
  const [selected, setSelected] = useState(null);

  useEffect(() => { setQ(initialQuery || ""); }, [initialQuery]);

  const states = ["All", ...Array.from(new Set(DESTINATIONS.map((d) => d.state))).sort()];
  const cats = ["All", "Heritage", "Nature", "Wildlife", "Spiritual", "Wellness", "Beaches", "Mountains", "Food", "Adventure", "Rural"];
  const seasons = ["All", "Winter (Oct–Mar)", "Summer (Apr–Jun)", "Monsoon (Jul–Sep)"];
  const sortOptions = ["Experience Score", "Safety Score", "Connectivity", "Name (A–Z)"];

  function matchesSeason(d) {
    if (seasonFilter === "All") return true;
    const s = d.bestSeason.toLowerCase();
    if (seasonFilter.startsWith("Winter")) return /oct|nov|dec|jan|feb|mar/.test(s);
    if (seasonFilter.startsWith("Summer")) return /apr|may|jun/.test(s);
    return /jul|aug|sep/.test(s);
  }

  const filtered = DESTINATIONS.filter((d) => {
    const mq = q.trim() === "" || d.name.toLowerCase().includes(q.toLowerCase()) || d.state.toLowerCase().includes(q.toLowerCase()) || d.categories.some(c => c.toLowerCase().includes(q.toLowerCase()));
    const ms = stateFilter === "All" || d.state === stateFilter;
    const mc = catFilter === "All" || d.categories.includes(catFilter);
    const macc = !accessibleOnly || d.accessibilityScore >= 60;
    return mq && ms && mc && macc && matchesSeason(d);
  }).sort((a, b) => {
    if (sortBy === "Experience Score") return b.experienceScore - a.experienceScore;
    if (sortBy === "Safety Score") return b.safetyScore - a.safetyScore;
    if (sortBy === "Connectivity") return b.connectivityScore - a.connectivityScore;
    return a.name.localeCompare(b.name);
  });

  return (
    <div style={{ maxWidth: 1320, margin: "0 auto", padding: "48px 24px 100px" }}>
      <SectionLabel>Discover India</SectionLabel>
      <h1 style={{ fontFamily: "Sora, sans-serif", fontSize: "clamp(28px, 3.6vw, 42px)", fontWeight: 700, marginBottom: 30 }}>
        Discover India beyond the obvious.
      </h1>

      <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginBottom: 30 }}>
        <div style={{ position: "relative", flex: "1 1 240px" }}>
          <Search size={15} style={{ position: "absolute", left: 12, top: 13, color: C.textSub }} />
          <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search destinations, states, interests…"
            style={{ width: "100%", background: C.cardEl, border: `1px solid ${C.border}`, borderRadius: 10, padding: "11px 14px 11px 34px", color: C.text, fontSize: 14 }} />
        </div>
        <select value={stateFilter} onChange={(e) => setStateFilter(e.target.value)} style={selectStyle}>
          {states.map((s) => <option key={s}>{s}</option>)}
        </select>
        <select value={catFilter} onChange={(e) => setCatFilter(e.target.value)} style={selectStyle}>
          {cats.map((c) => <option key={c}>{c}</option>)}
        </select>
        <select value={seasonFilter} onChange={(e) => setSeasonFilter(e.target.value)} style={selectStyle}>
          {seasons.map((s) => <option key={s}>{s}</option>)}
        </select>
        <select value={sortBy} onChange={(e) => setSortBy(e.target.value)} style={selectStyle}>
          {sortOptions.map((s) => <option key={s} value={s}>Sort: {s}</option>)}
        </select>
        <label style={{ display: "flex", alignItems: "center", gap: 7, ...selectStyle, cursor: "pointer" }}>
          <input type="checkbox" checked={accessibleOnly} onChange={(e) => setAccessibleOnly(e.target.checked)} />
          Accessible-friendly only
        </label>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1.1fr 1fr", gap: 28, marginBottom: 44 }} className="b360-discover-grid">
        <Card style={{ padding: 0, overflow: "hidden", height: 430, display: "flex", flexDirection: "column" }}>
          <div style={{ padding: "16px 18px", borderBottom: `1px solid ${C.border}`, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <div style={{ fontWeight: 700, fontSize: 14.5 }}>Destinations across India</div>
            <DataLabel>Navigable map</DataLabel>
          </div>
          <div style={{ position: "relative", flex: 1 }}>
            <IndiaLeafletMap destinations={filtered} onPick={setSelected} selected={selected} />
          </div>
        </Card>
        <Card style={{ height: 430, display: "flex", flexDirection: "column", overflow: "hidden" }}>
          {selected ? (
            <div>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                <div>
                  <div style={{ fontWeight: 700, fontSize: 19, fontFamily: "Sora, sans-serif" }}>{selected.name}</div>
                  <div style={{ color: C.textSub, fontSize: 13 }}>{selected.state}</div>
                </div>
                <Pill tone="success"><Star size={11} fill={C.success} /> {selected.experienceScore}/100</Pill>
              </div>
              <p style={{ color: C.textSub, fontSize: 13.8, lineHeight: 1.6, marginTop: 14, display: "-webkit-box", WebkitLineClamp: 3, WebkitBoxOrient: "vertical", overflow: "hidden" }}>{selected.desc}</p>
              <Button variant="primary" onClick={() => openDestination(selected)} style={{ marginTop: 16 }} icon={ChevronRight}>View destination</Button>
            </div>
          ) : (
            <div style={{ color: C.textSub, fontSize: 14, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", flex: "0 0 auto", textAlign: "center", padding: "20px 0" }}>
              <MapPin size={28} color={C.border} style={{ marginBottom: 10 }} />
              Select a marker on the map, or a card below, to preview a destination.
            </div>
          )}

          <div style={{ marginTop: 22, paddingTop: 20, borderTop: `1px solid ${C.border}`, overflowY: "auto" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}>
              <TrendingUp size={15} color={C.accent} />
              <div style={{ fontWeight: 700, fontSize: 14 }}>Beyond the usual route</div>
            </div>
            <div style={{ color: C.textSub, fontSize: 13.5, lineHeight: 1.6 }}>
              Planning Jaipur? Consider adding <b style={{ color: C.text }}>Bundi</b> — a similar heritage experience with a quieter travel environment.
            </div>
          </div>
        </Card>
      </div>

      <div style={{ fontWeight: 700, fontSize: 16, marginTop: 8, marginBottom: 18 }}>{filtered.length} destination{filtered.length !== 1 ? "s" : ""}</div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(260px, 1fr))", gap: 18 }}>
        {filtered.map((d) => <DestinationCard key={d.id} d={d} onOpen={openDestination} />)}
        {filtered.length === 0 && <div style={{ color: C.textSub }}>No destinations match these filters yet.</div>}
      </div>
      <style>{`@media (max-width: 900px) { .b360-discover-grid { grid-template-columns: 1fr !important; } }`}</style>
    </div>
  );
}

const selectStyle = { background: C.cardEl, border: `1px solid ${C.border}`, borderRadius: 10, padding: "11px 12px", color: C.text, fontSize: 13.5 };

// Real-world lat/lng for each destination, used by the Leaflet map below
const DEST_LATLNG = {
  maheshwar: [22.1737, 75.5876], mandu: [22.3410, 75.3771], hampi: [15.3350, 76.4600],
  majuli: [26.9500, 94.1500], ziro: [27.5449, 93.8317], gokarna: [14.5479, 74.3188],
  spiti: [32.2465, 78.0169], bundi: [25.4305, 75.6499],
  munnar: [10.0889, 77.0595], kanyakumari: [8.0883, 77.5385], "old-goa": [15.5007, 73.9114],
  rishikesh: [30.0869, 78.2676], leh: [34.1526, 77.5771], varanasi: [25.3176, 82.9739],
  darjeeling: [27.0410, 88.2663], amritsar: [31.6340, 74.8723], "rann-of-kutch": [23.7337, 69.8597],
  puri: [19.8135, 85.8312], "araku-valley": [18.3273, 82.8770], gangtok: [27.3389, 88.6065],
  jaipur: [26.9124, 75.7873], udaipur: [24.5854, 73.7125], agra: [27.1751, 78.0421],
  mumbai: [19.0760, 72.8777], delhi: [28.6139, 77.2090], shimla: [31.1048, 77.1734],
  manali: [32.2396, 77.1887], pondicherry: [11.9416, 79.8083], coorg: [12.4244, 75.7382],
  "havelock-island": [11.9770, 92.9860],
  kolkata: [22.5726, 88.3639], jodhpur: [26.2389, 73.0243], jaisalmer: [26.9157, 70.9083],
  kochi: [9.9312, 76.2673], alleppey: [9.4981, 76.3388], mysuru: [12.2958, 76.6394],
  hyderabad: [17.3850, 78.4867], khajuraho: [24.8318, 79.9199], "jim-corbett": [29.5300, 78.7747],
  ooty: [11.4102, 76.6950], chitrakote: [19.2067, 81.7000],
};

// Loads Leaflet from a CDN at runtime (no npm install / bundler resolution needed)
let _leafletLoadPromise = null;
function loadLeaflet() {
  if (typeof window !== "undefined" && window.L) return Promise.resolve(window.L);
  if (_leafletLoadPromise) return _leafletLoadPromise;
  _leafletLoadPromise = new Promise((resolve, reject) => {
    if (!document.getElementById("b360-leaflet-css")) {
      const link = document.createElement("link");
      link.id = "b360-leaflet-css";
      link.rel = "stylesheet";
      link.href = "https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.css";
      document.head.appendChild(link);
    }
    const existing = document.getElementById("b360-leaflet-js");
    if (existing) {
      existing.addEventListener("load", () => resolve(window.L));
      existing.addEventListener("error", reject);
      return;
    }
    const script = document.createElement("script");
    script.id = "b360-leaflet-js";
    script.src = "https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.js";
    script.async = true;
    script.onload = () => resolve(window.L);
    script.onerror = reject;
    document.body.appendChild(script);
  });
  return _leafletLoadPromise;
}

function makeDestIcon(Lref, color) {
  return Lref.divIcon({
    className: "b360-map-pin",
    html: `<div style="width:16px;height:16px;border-radius:50%;background:${color};border:2px solid #fff;box-shadow:0 0 0 2px rgba(0,0,0,0.25);"></div>`,
    iconSize: [16, 16],
    iconAnchor: [8, 8],
  });
}

function IndiaLeafletMap({ destinations, onPick, selected }) {
  const mapElRef = useRef(null);
  const mapRef = useRef(null);
  const markersRef = useRef({});
  const [ready, setReady] = useState(false);

  // load leaflet + init map once
  useEffect(() => {
    let cancelled = false;
    loadLeaflet()
      .then((Lref) => {
        if (cancelled || mapRef.current || !mapElRef.current) return;
        const map = Lref.map(mapElRef.current, {
          center: [22.5, 80.5],
          zoom: 4.6,
          minZoom: 4,
          maxZoom: 12,
          scrollWheelZoom: true,
        });
        Lref.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
          attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
        }).addTo(map);
        mapRef.current = map;
        setTimeout(() => map.invalidateSize(), 0);
        setReady(true);
      })
      .catch(() => setReady(false));
    return () => {
      cancelled = true;
      if (mapRef.current) {
        mapRef.current.remove();
        mapRef.current = null;
      }
    };
  }, []);

  // sync markers with destinations/selection
  useEffect(() => {
    const map = mapRef.current;
    const Lref = typeof window !== "undefined" ? window.L : null;
    if (!map || !Lref || !ready) return;
    const existingIds = Object.keys(markersRef.current);
    const nextIds = destinations.map((d) => d.id);

    existingIds.forEach((id) => {
      if (!nextIds.includes(id)) {
        map.removeLayer(markersRef.current[id]);
        delete markersRef.current[id];
      }
    });

    destinations.forEach((d) => {
      const ll = DEST_LATLNG[d.id];
      if (!ll) return;
      const isSel = selected && selected.id === d.id;
      const icon = makeDestIcon(Lref, isSel ? C.accent : C.accent2);
      if (markersRef.current[d.id]) {
        markersRef.current[d.id].setIcon(icon);
      } else {
        const marker = Lref.marker(ll, { icon }).addTo(map);
        marker.bindTooltip(d.name, { direction: "top", offset: [0, -6] });
        marker.on("click", () => onPick(d));
        markersRef.current[d.id] = marker;
      }
    });
  }, [destinations, selected, ready]);

  return (
    <div style={{ width: "100%", height: "100%", position: "relative" }}>
      <div ref={mapElRef} style={{ width: "100%", height: "100%" }} />
      {!ready && (
        <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", color: C.textSub, fontSize: 13.5 }}>
          Loading map…
        </div>
      )}
    </div>
  );
}

