function DetailSection({ icon: Icon, title, children }) {
  return (
    <div>
      <div style={{ display: "flex", alignItems: "center", gap: 9, marginBottom: 12 }}>
        <Icon size={16} color={C.accent} />
        <div style={{ fontWeight: 700, fontSize: 16, fontFamily: "Sora, sans-serif" }}>{title}</div>
      </div>
      {children}
    </div>
  );
}

/* ============================================================
   PLAN YOUR JOURNEY
   ============================================================ */
function PlanJourney() {
  const [form, setForm] = useState({
    destinationId: "auto", from: "", duration: 7, budget: "Moderate", type: "Couple",
    interests: ["Culture"], pace: "Balanced", accessibility: "None", language: "English",
  });
  const [result, setResult] = useState(null);

  const interestOptions = ["Culture", "Nature", "Food", "Wildlife", "Adventure", "Spirituality", "Wellness", "Beaches"];

  function toggleInterest(i) {
    setForm((f) => ({ ...f, interests: f.interests.includes(i) ? f.interests.filter((x) => x !== i) : [...f.interests, i] }));
  }

  // Builds a real day-by-day plan for ONE chosen destination, using that place's own
  // experiences, food, transport and accessibility data — not a generic template.
  function buildSingleDestinationPlan(d, duration, accessibilityNeed) {
    const days = [];
    const activitiesPerDay = form.pace === "Packed" ? 3 : form.pace === "Relaxed" ? 1 : 2;
    const pool = [...d.experiences];
    let cursor = 0;

    days.push({
      label: "Day 1 — Arrival",
      title: `Arrive in ${d.name}`,
      body: d.howToReach,
      tag: "Arrival",
    });

    const middleDays = Math.max(0, duration - 2);
    for (let i = 0; i < middleDays; i++) {
      const picks = [];
      for (let a = 0; a < activitiesPerDay; a++) {
        picks.push(pool[cursor % pool.length]);
        cursor++;
      }
      days.push({
        label: `Day ${i + 2}`,
        title: picks[0],
        body: picks.join(" · "),
        tag: "Experience",
      });
    }

    if (duration > 1) {
      days.push({
        label: `Day ${duration} — Departure`,
        title: `Depart from ${d.name}`,
        body: d.localTransport,
        tag: "Departure",
      });
    }

    const accessibilityNote = accessibilityNeed !== "None"
      ? `Accessibility note for ${accessibilityNeed.toLowerCase()}: ${d.accessibility}`
      : null;

    return { mode: "single", destination: d, days, food: d.food, safety: d.safetyNotes, accessibilityNote, bestSeason: d.bestSeason };
  }

  function buildMultiDestinationPlan(duration) {
    const matches = DESTINATIONS
      .map((d) => {
        let score = 0;
        form.interests.forEach((i) => { if (d.categories.some(c => c.toLowerCase() === i.toLowerCase()) || (i === "Culture" && d.categories.includes("Heritage")) || (i === "Wildlife" && d.categories.includes("Nature"))) score += 2; });
        score += d.experienceScore / 40;
        return { d, score };
      })
      .sort((a, b) => b.score - a.score)
      .slice(0, Math.min(5, Math.max(3, Math.round(duration / 3))));

    const days = [];
    let dayCursor = 1;
    matches.forEach((m, idx) => {
      const span = idx === 0 ? 2 : Math.max(1, Math.round(duration / matches.length));
      const start = dayCursor;
      const end = Math.min(duration, dayCursor + span - 1);
      days.push({ label: end > start ? `Day ${start}–${end}` : `Day ${start}`, dest: m.d });
      dayCursor = end + 1;
    });

    return { mode: "multi", days, matches };
  }

  function build(e) {
    e.preventDefault();
    if (form.destinationId !== "auto") {
      const d = DESTINATIONS.find((x) => x.id === form.destinationId);
      setResult(buildSingleDestinationPlan(d, form.duration, form.accessibility));
    } else {
      setResult(buildMultiDestinationPlan(form.duration));
    }
  }

  return (
    <div style={{ maxWidth: 1320, margin: "0 auto", padding: "48px 24px 100px" }}>
      <SectionLabel>Plan Your Journey</SectionLabel>
      <h1 style={{ fontFamily: "Sora, sans-serif", fontSize: "clamp(28px, 3.6vw, 42px)", fontWeight: 700, marginBottom: 30 }}>Plan India around you.</h1>

      <div style={{ display: "grid", gridTemplateColumns: "420px 1fr", gap: 30 }} className="b360-plan-grid">
        <Card as="form">
          <form onSubmit={build}>
            <Field label="Destination">
              <select value={form.destinationId} onChange={(e) => setForm({ ...form, destinationId: e.target.value })} style={selectStyle}>
                <option value="auto">Best match for my interests</option>
                {DESTINATIONS.map((d) => <option key={d.id} value={d.id}>{d.name}, {d.state}</option>)}
              </select>
            </Field>
            <Field label="Where are you travelling from?">
              <input value={form.from} onChange={(e) => setForm({ ...form, from: e.target.value })} placeholder="e.g. Mumbai" style={inputStyle} />
            </Field>
            <Field label={`Trip duration — ${form.duration} days`}>
              <input type="range" min="3" max="21" value={form.duration} onChange={(e) => setForm({ ...form, duration: Number(e.target.value) })} style={{ width: "100%" }} />
            </Field>
            <Field label="Budget">
              <div style={{ display: "flex", gap: 8 }}>
                {["Budget", "Moderate", "Premium"].map((b) => <Chip key={b} active={form.budget === b} onClick={() => setForm({ ...form, budget: b })}>{b}</Chip>)}
              </div>
            </Field>
            <Field label="Travel type">
              <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                {["Solo", "Couple", "Family", "Friends"].map((b) => <Chip key={b} active={form.type === b} onClick={() => setForm({ ...form, type: b })}>{b}</Chip>)}
              </div>
            </Field>
            <Field label="Interests">
              <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                {interestOptions.map((b) => <Chip key={b} active={form.interests.includes(b)} onClick={() => toggleInterest(b)}>{b}</Chip>)}
              </div>
            </Field>
            <Field label="Preferred pace">
              <div style={{ display: "flex", gap: 8 }}>
                {["Relaxed", "Balanced", "Packed"].map((b) => <Chip key={b} active={form.pace === b} onClick={() => setForm({ ...form, pace: b })}>{b}</Chip>)}
              </div>
            </Field>
            <Field label="Accessibility needs">
              <select value={form.accessibility} onChange={(e) => setForm({ ...form, accessibility: e.target.value })} style={selectStyle}>
                {["None", "Wheelchair friendly", "Limited walking", "Family friendly"].map((o) => <option key={o}>{o}</option>)}
              </select>
            </Field>
            <Field label="Language">
              <select value={form.language} onChange={(e) => setForm({ ...form, language: e.target.value })} style={selectStyle}>
                {["English", "Hindi", "Other"].map((o) => <option key={o}>{o}</option>)}
              </select>
            </Field>
            <Button type="submit" variant="primary" style={{ width: "100%", justifyContent: "center", marginTop: 8 }}>Build My Journey</Button>
          </form>
        </Card>

        <div>
          {!result ? (
            <Card style={{ height: "100%", display: "flex", alignItems: "center", justifyContent: "center", textAlign: "center", color: C.textSub, minHeight: 340 }}>
              <div>
                <Route size={30} color={C.border} style={{ marginBottom: 10 }} />
                <div style={{ fontSize: 14 }}>Your itinerary will appear here once you build your journey.</div>
              </div>
            </Card>
          ) : result.mode === "single" ? (
            <div>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16, flexWrap: "wrap", gap: 8 }}>
                <div style={{ fontWeight: 700, fontSize: 18, fontFamily: "Sora, sans-serif" }}>Your {form.duration}-day {result.destination.name} itinerary</div>
                <Pill tone="success">Best season: {result.bestSeason}</Pill>
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: 12, marginBottom: 22 }}>
                {result.days.map((day, i) => (
                  <Card key={i} style={{ padding: 16 }} hover={false}>
                    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6 }}>
                      <div style={{ color: C.accent, fontWeight: 700, fontSize: 13.5 }}>{day.label}</div>
                      <Pill tone={day.tag === "Arrival" ? "default" : day.tag === "Departure" ? "muted" : "success"}>{day.tag}</Pill>
                    </div>
                    <div style={{ fontWeight: 700, fontSize: 15 }}>{day.title}</div>
                    <div style={{ color: C.textSub, fontSize: 13, marginTop: 4, lineHeight: 1.55 }}>{day.body}</div>
                  </Card>
                ))}
              </div>
              <Card style={{ background: C.bg2, marginBottom: 14 }} hover={false}>
                <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 10 }}>Good to know</div>
                <div style={{ fontSize: 13, color: C.textSub, lineHeight: 1.6, marginBottom: 8 }}><b style={{ color: C.text }}>Food:</b> {result.food}</div>
                <div style={{ fontSize: 13, color: C.textSub, lineHeight: 1.6, marginBottom: result.accessibilityNote ? 8 : 0 }}><b style={{ color: C.text }}>Safety:</b> {result.safety}</div>
                {result.accessibilityNote && <div style={{ fontSize: 13, color: C.textSub, lineHeight: 1.6 }}><b style={{ color: C.text }}>Accessibility:</b> {result.accessibilityNote.replace(/^Accessibility note for [^:]+: /, "")}</div>}
              </Card>
              <DataLabel>Built from {result.destination.name}'s own experience, transport and safety data</DataLabel>
            </div>
          ) : (
            <div>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
                <div style={{ fontWeight: 700, fontSize: 18, fontFamily: "Sora, sans-serif" }}>Your {form.duration}-day journey</div>
                <DataLabel>Interest-based recommendation engine</DataLabel>
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: 12, marginBottom: 26 }}>
                {result.days.map((day, i) => (
                  <Card key={i} style={{ display: "flex", gap: 16, alignItems: "center", padding: 16, cursor: "pointer" }} hover={false} onClick={() => { setForm((f) => ({ ...f, destinationId: day.dest.id })); setResult(buildSingleDestinationPlan(day.dest, form.duration, form.accessibility)); }}>
                    <div style={{ minWidth: 90, color: C.accent, fontWeight: 700, fontSize: 13.5 }}>{day.label}</div>
                    <div style={{ width: 52, height: 52, borderRadius: 8, backgroundImage: `url(${day.dest.img}), linear-gradient(135deg, #1f3a3d, #0d1a24)`, backgroundSize: "cover", backgroundPosition: "center", flexShrink: 0 }} />
                    <div>
                      <div style={{ fontWeight: 700, fontSize: 15 }}>{day.dest.name}</div>
                      <div style={{ color: C.textSub, fontSize: 12.5 }}>{day.dest.state} — {day.dest.tags}</div>
                    </div>
                  </Card>
                ))}
              </div>
              <Card style={{ background: C.bg2 }} hover={false}>
                <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 12 }}>Recommendation factors</div>
                <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(150px, 1fr))", gap: 10 }}>
                  {["Interest match", "Travel time", "Season suitability", "Destination diversity", "Local experiences"].map((f) => (
                    <div key={f} style={{ display: "flex", gap: 8, alignItems: "center", fontSize: 13, color: C.textSub }}>
                      <CheckCircle2 size={14} color={C.success} />{f}
                    </div>
                  ))}
                </div>
                <div style={{ marginTop: 12, fontSize: 12.5, color: C.textSub, lineHeight: 1.6 }}>
                  Recommendations consider your selected interests, relative travel time between destinations, seasonal suitability, and a mix of destination types. Click any destination above to build a detailed day-by-day plan for just that place.
                </div>
              </Card>
            </div>
          )}
        </div>
      </div>
      <style>{`@media (max-width: 900px) { .b360-plan-grid { grid-template-columns: 1fr !important; } }`}</style>
    </div>
  );
}
function Field({ label, children }) {
  return (
    <div style={{ marginBottom: 18 }}>
      <div style={{ fontSize: 13, color: C.textSub, marginBottom: 8, fontWeight: 500 }}>{label}</div>
      {children}
    </div>
  );
}
const inputStyle = { width: "100%", background: C.cardEl, border: `1px solid ${C.border}`, borderRadius: 9, padding: "10px 12px", color: C.text, fontSize: 14 };
function Chip({ children, active, onClick }) {
  return (
    <button type="button" onClick={onClick} style={{
      border: `1px solid ${active ? C.accent : C.border}`, background: active ? "rgba(155,31,174,0.14)" : C.cardEl,
      color: active ? C.accent2 : C.textSub, borderRadius: 20, padding: "7px 14px", fontSize: 13, cursor: "pointer", fontWeight: 500,
    }}>{children}</button>
  );
}

