function FooterCol({ title, items, setView }) {
  return (
    <div>
      <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 12, color: C.text }}>{title}</div>
      {items.map(([label, key]) => (
        <div key={key} onClick={() => setView(key)} style={{ color: C.textSub, fontSize: 13, marginBottom: 10, cursor: "pointer" }}>{label}</div>
      ))}
    </div>
  );
}

/* ============================================================
   ROOT APP
   ============================================================ */
export default function IndiaQuestApp() {
  const [view, setViewRaw] = useState("home");
  const [mode, setMode] = useState("Tourist");
  const [lang, setLang] = useState("en");
  const [selectedDestination, setSelectedDestination] = useState(null);
  const [query, setQuery] = useState("");
  const [searchQuery, setSearchQuery] = useState("");
  const [reports, setReports] = useState(SEED_REPORTS);
  const [users, setUsers] = useState([{ username: "demo", password: "demo1234", email: "demo@indiaquest.in" }]);
  const [currentUser, setCurrentUser] = useState(null);
  const [authOpen, setAuthOpen] = useState(false);
  const [authMode, setAuthMode] = useState("login");
  const [authError, setAuthError] = useState("");
  const scrollRef = useRef(null);

  function openAuth(mode) { setAuthMode(mode); setAuthError(""); setAuthOpen(true); }
  function handleLogin(username, password) {
    const u = users.find((x) => x.username.toLowerCase() === username.toLowerCase() && x.password === password);
    if (!u) { setAuthError("Incorrect username or password. Try the demo account: demo / demo1234."); return; }
    setCurrentUser(u); setAuthOpen(false);
  }
  function handleSignup(username, email, password) {
    if (!username || !email || password.length < 4) { setAuthError("Please fill in all fields — password needs at least 4 characters."); return; }
    if (users.some((x) => x.username.toLowerCase() === username.toLowerCase())) { setAuthError("That username is already taken."); return; }
    const u = { username, email, password };
    setUsers((prev) => [...prev, u]);
    setCurrentUser(u); setAuthOpen(false);
  }
  function handleLogout() { setCurrentUser(null); }

  const t = { ...STRINGS[lang], hero_sub: "Discover destinations, trusted local services, safer journeys and the experiences beyond the usual tourist routes." };

  function setView(v) {
    setViewRaw(v);
    window.scrollTo({ top: 0, behavior: "instant" in window ? "instant" : "auto" });
  }
  function openDestination(d) { setSelectedDestination(d); setView("destination"); }
  function addReport(r) { setReports((prev) => [r, ...prev]); }
  function onSearch(q) { setSearchQuery(q); setView("discover"); }

  let content;
  if (view === "home") content = <HomePage setView={setView} t={t} openDestination={openDestination} />;
  else if (view === "discover") content = <DiscoverPage openDestination={openDestination} initialQuery={searchQuery} />;
  else if (view === "destination") content = <DestinationDetail d={selectedDestination} setView={setView} />;
  else if (view === "plan") content = <PlanJourney />;
  else if (view === "trusted") content = <TrustedIndia />;
  else if (view === "safety") content = <SafetyPage />;
  else if (view === "report") content = <ReportPage addReport={addReport} currentUser={currentUser} onOpenAuth={openAuth} />;
  else if (view === "intelligence") content = <IntelligenceDashboard reports={reports} />;
  else if (view === "business") content = <BusinessView />;
  else content = <HomePage setView={setView} t={t} openDestination={openDestination} />;

  return (
    <div style={{ background: C.bg, minHeight: "100vh", color: C.text, fontFamily: "Inter, system-ui, sans-serif" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Sora:wght@600;700;800&display=swap');
        html, body { height: auto !important; overflow-x: hidden; overflow-y: auto !important; margin: 0; }
        #root, #__next { height: auto !important; overflow: visible !important; }
        * { box-sizing: border-box; }
        input, select, textarea { font-family: 'Inter', sans-serif; }
        input:focus, select:focus, textarea:focus, button:focus { outline: 1.5px solid ${C.accent}; outline-offset: 1px; }
        ::-webkit-scrollbar { width: 8px; height: 8px; }
        ::-webkit-scrollbar-thumb { background: ${C.border}; border-radius: 8px; }
        table th { text-transform: none; }
        @media (prefers-reduced-motion: reduce) { * { transition: none !important; } }
        .b360-hide-scrollbar::-webkit-scrollbar { display: none; }
        .b360-hide-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
      `}</style>
      <div id="indiaquest-scroll-root" ref={scrollRef}>
        <Navbar view={view} setView={setView} t={t} lang={lang} setLang={setLang} mode={mode} setMode={setMode} query={query} setQuery={setQuery} onSearch={onSearch} currentUser={currentUser} onOpenAuth={openAuth} onLogout={handleLogout} />
        {content}
        <Footer setView={setView} />
      </div>
      <AuthModal open={authOpen} mode={authMode} setMode={setAuthMode} onClose={() => setAuthOpen(false)} onLogin={handleLogin} onSignup={handleSignup} error={authError} />
    </div>
  );
}

